// "dispatch input leg > label agent:rework > label agent:review >
// assignee/agent:dev (dev)"). pr_approved arms the review leg.
var ARMING_LABEL_LEGS = {
    'agent:dev': 'dev',
    'agent:develop': 'dev',
    'agent:review': 'review',
    'agent:rework': 'rework',
    'pr_approved': 'review'
