        eventName: 'issues',
        action: 'assigned',
        issue: ISSUE,
        issueLabelNames: opts.issueLabelNames || [],
        runs: opts.runs || [],
        selfRun: opts.selfRun || selfRun(500),
        nowMs: opts.nowMs !== undefined ? opts.nowMs : NOW_MS
    };
}

function labeledEvent(labelName, opts) {
    opts = opts || {};
    return {
        eventName: 'issues',
        action: 'labeled',
        labelName: labelName,
        issue: ISSUE,
        issueLabelNames: opts.issueLabelNames || [],
        runs: opts.runs || [],
        selfRun: opts.selfRun || selfRun(501),
        nowMs: opts.nowMs !== undefined ? opts.nowMs : NOW_MS
    };
}

