    if (opts.conclusion) r.conclusion = opts.conclusion;
    return r;
}

function selfRun(runNumber, opts) {
    opts = opts || {};
    return {
        id: opts.id !== undefined ? opts.id : 800000 + runNumber,
        runNumber: runNumber,
        createdAt: opts.createdAt || NOW_MS
    };
}

function assignedEvent(opts) {
    opts = opts || {};
    return {
        eventName: 'issues',
        action: 'assigned',
        issue: ISSUE,
