{"content":"#!/usr/bin/env node
// Transport smoke: execute the DEDUP_PROBE_EOF block from
// .github/workflows/ai-teammate.yml against a mocked `gh` on PATH.
// Verifies: duplicate drop, earliest-proceeds tie-break, degraded fail-open,
// dispatch preflight (zero API), non-arming preflight (zero API),
// JSON label lists with spaces.
const { execFileSync, writeFileSync, chmodSync, mkdirSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const yml = fs.readFileSync('.github/workflows/ai-teammate.yml', 'utf8');
const m = yml.match(/node <<'DEDUP_PROBE_EOF'\n([\s\S]*?)\n\s*DEDUP_PROBE_EOF/);
if (!m) { console.error('probe block not found'); process.exit(1); }
const probeSrc = m[1].replace(/^          /gm, '');
fs.writeFileSync('/tmp/probe_extracted.js', probeSrc);

// ── mocked gh ────────────────────────────────────────────────────────────
mkdirSync('/tmp/fakebin', { recursive: true });
const ghMock = `#!/usr/bin/env node
// responds to: gh api repos/R/actions/workflows/ai-teammate.yml/runs -f status=S ...
const status = (process.argv.join(' ').match(/status=([a-z_]+)/) || [])[1];
const scenario = process.env.MOCK_SCENARIO;
const line = (o) => console.log(JSON.stringify(o));
const LEG = '.github/workflows/ai-teammate.yml';
if (scenario === 'dup') {
  if (status === 'in_progress') {
    line({ id: 800500, run_number: 500, name: 'teammate: issues #1040 ', status: 'in_progress', path: LEG, created_at: '2026-10-18T20:11:00Z', updated_at: '2026-10-18T20:11:00Z' });
  }
} else if (scenario === 'burst') {
  if (status === 'in_progress') line({ id: 1, run_number: 500, name: 'teammate: issues #1040 ', status: 'in_progress', path: LEG, created_at: '2026-10-18T20:11:00Z', updated_at: '2026-10-18T20:11:00Z' });
  if (status === 'queued') line({ id: 2, run_number: 501, name: 'teammate: issues #1040 ', status: 'queued', path: LEG, created_at: '2026-10-18T20:11:01Z', updated_at: '2026-10-18T20:11:01Z' });
} else if (scenario === 'degraded') {
  console.error('boom'); process.exit(1);
} else if (scenario === 'fresh-success') {
  if (status === 'completed') line({ id: 1, run_number: 500, name: 'teammate: issues #1040 dev', status: 'completed', conclusion: 'success', path: LEG, created_at: '2026-10-18T20:08:00Z', updated_at: '2026-10-18T20:08:30Z' });
}
`;
fs.writeFileSync('/tmp/fakebin/gh', ghMock);
chmodSync('/tmp/fakebin/gh', 0o755);

// ── probe runner ─────────────────────────────────────────────────────────
function runProbe(env) {
  const outFile = '/tmp/probe_out_' + Math.random().toString(36).slice(2);
  const fullEnv = Object.assign({}, process.env, {
    PATH: '/tmp/fakebin:' + process.env.PATH,
    GITHUB_OUTPUT: outFile,
    GH_TOKEN: 'x', REPO: 'IstiN/dmtools-agents',
    WORKFLOW_FILE: 'ai-teammate.yml',
    SELF_ID: '800501', SELF_RUN_NUMBER: '501',
    ISSUE_LABELS: '["agent:dev","status:in progress"]',
    ASSIGNEES: '["ai-teammate"]',
    LABEL_NAME: ''
  }, env);
  let stdout = '';
  try {
    stdout = execFileSync('node', ['/tmp/probe_extracted.js'], { env: fullEnv, encoding: 'utf8' });
  } catch (e) {
    return { crashed: true, stdout: String(e.stdout || '') + String(e.message) };
  }
  const outputs = {};
  try {
    fs.readFileSync(outFile, 'utf8').split('\n').forEach((l) => {
      const idx = l.indexOf('=');
      if (idx > 0) outputs[l.slice(0, idx)] = l.slice(idx + 1);
    });
  } catch (e) { /* no output file */ }
  return { outputs, stdout };
}

let failures = 0;
function check(name, cond, detail) {
  console.log((cond ? '  ✅ ' : '  ❌ ') + name + (cond ? '' : ' — ' + detail));
  if (!cond) failures++;
}

// 1. duplicate drop: older in-flight owner for the same issue
let r = runProbe({ MOCK_SCENARIO: 'dup', EVENT_NAME: 'issues', ACTION: 'assigned', ISSUE: '1040', LABEL_NAME: '' });
check('duplicate drop: proceed=false', r.outputs && r.outputs.proceed === 'false', JSON.stringify(r));
check('duplicate drop: audit present', r.outputs && /gh-1065/.test(r.outputs.audit || ''), JSON.stringify(r.outputs));

// 2. earliest-proceeds tie-break: self is run 501 of a 500/501 burst
r = runProbe({ MOCK_SCENARIO: 'burst', EVENT_NAME: 'issues', ACTION: 'labeled', LABEL_NAME: 'agent:dev', ISSUE: '1040' });
check('burst: the LATER run (501) drops', r.outputs && r.outputs.proceed === 'false', JSON.stringify(r.outputs));
r = runProbe({ MOCK_SCENARIO: 'burst', EVENT_NAME: 'issues', ACTION: 'labeled', LABEL_NAME: 'agent:dev', ISSUE: '1040', SELF_RUN_NUMBER: '500', SELF_ID: '1' });
check('burst: the EARLIEST run (500) proceeds', r.outputs && r.outputs.proceed === 'true', JSON.stringify(r.outputs));

// 3. degraded fail-open: every gh call fails
r = runProbe({ MOCK_SCENARIO: 'degraded', EVENT_NAME: 'issues', ACTION: 'assigned', ISSUE: '1040' });
check('degraded: proceed=true (fail-open)', r.outputs && r.outputs.proceed === 'true', JSON.stringify(r));
check('degraded: audit mentions fail-open', r.outputs && /fail-open/.test(r.outputs.audit || ''), JSON.stringify(r.outputs));

// 4. dispatch preflight: no API burn, proceed=true
r = runProbe({ MOCK_SCENARIO: 'degraded', EVENT_NAME: 'workflow_dispatch', ACTION: '', ISSUE: '1040' });
check('dispatch preflight: proceeds despite broken gh (zero API burn)', r.outputs && r.outputs.proceed === 'true', JSON.stringify(r));
check('dispatch preflight: audit names the dispatch path', r.outputs && /dispatch path/.test(r.outputs.audit || ''), JSON.stringify(r.outputs));

// 5. non-arming label preflight: no API burn
r = runProbe({ MOCK_SCENARIO: 'degraded', EVENT_NAME: 'issues', ACTION: 'labeled', LABEL_NAME: 'status:in_progress', ISSUE: '1040' });
check('non-arming label: proceeds without API', r.outputs && r.outputs.proceed === 'true', JSON.stringify(r));
check('non-arming label: audit names the gate', r.outputs && /non-arming label/.test(r.outputs.audit || ''), JSON.stringify(r.outputs));

// 6. fresh-success owner with a CARRIED leg drops the same-leg burst duplicate
r = runProbe({ MOCK_SCENARIO: 'fresh-success', EVENT_NAME: 'issues', ACTION: 'labeled', LABEL_NAME: 'agent:dev', ISSUE: '1040' });
check('fresh-success (dev leg): agent:dev duplicate drops', r.outputs && r.outputs.proceed === 'false', JSON.stringify(r.outputs));

// 7. fresh-success owner with a carried leg does NOT swallow a different known leg
r = runProbe({ MOCK_SCENARIO: 'fresh-success', EVENT_NAME: 'issues', ACTION: 'labeled', LABEL_NAME: 'agent:review', ISSUE: '1040' });
check('fresh-success (dev leg): agent:review proceeds (sequential action)', r.outputs && r.outputs.proceed === 'true', JSON.stringify(r.outputs));

// 8. JSON list with a space-y label parsed intact (probe ran with status:in progress above; here assert the parse via assignee check)
r = runProbe({ MOCK_SCENARIO: 'degraded', EVENT_NAME: 'issues', ACTION: 'assigned', ISSUE: '1040', ASSIGNEES: '["human user"]' });
check('space-y assignee JSON does not crash the probe', r.outputs && r.outputs.proceed === 'true', JSON.stringify(r));

console.log(failures === 0 ? '\nALL TRANSPORT SMOKE CHECKS PASSED' : '\n' + failures + ' CHECKS FAILED');
process.exit(failures === 0 ? 0 : 1);
