```js
// Collect every folded job-level `if: >-` scalar ...
function foldedIfBlocks(yml) {
   var blocks = [];
   var lines = yml.split('\n');
   for (var i = 0; i < lines.length; i++) {
       if (!/^ {4}if: >-\s*$/.test(lines[i])) continue;
       var parts = [];
       for (var j = i + 1; j < lines.length; j++) {
           if (/^\s*$/.test(lines[j])) continue;
           if (!/^ {5,}/.test(lines[j])) break;
           parts.push(lines[j].replace(/^\s+/, ''));
       }
       blocks.push(parts.join(' '));
   }
   return blocks;
}

// gh-1065: the stub carries TWO such gates ... this contract targets the
